mapper.select:
SELECT
    u.id, u.nickname, u.avatar, u.status, u.created_at, u.updated_at,
    up.gender, up.birthday, up.province, up.city, up.address, up.company, up.bio
FROM `user` u
LEFT JOIN user_profiles up ON u.id = up.user_id

    u.id >= #{nextCursor}
    AND u.status = #{status}
    AND up.gender = #{gender}
    AND up.birthday >= #{beginDate}
    AND up.birthday <= #{endDate}
    AND up.province = #{province}
    AND up.city = #{city}

ORDER BY u.id ASC
LIMIT #{pageSize}
